  "Use /explain <command>, e.g. /explain low": "استخدم /explain <الأمر>، مثل /explain low",
  "Use /price <product> <amount>, e.g. /price Tea 100g 0.450":
    "استخدم /price <المنتج> <المبلغ>، مثل /price شاي 100غ 0.450",
  "Use /{0} <kind> <name or id>. Kinds: {1}": "استخدم /{0} <النوع> <الاسم أو المعرّف>. الأنواع: {1}",
  "Use a clear photo or scan (PNG or JPG). For a PDF invoice, save the page as an image first.":
    "استخدم صورة أو مسحاً واضحاً (PNG أو JPG). لفاتورة PDF احفظ الصفحة كصورة أولاً.",
  "Use an API key, not a chat subscription": "استخدم مفتاح API وليس اشتراك دردشة",
  "Use either a fixed or a percentage cart discount, not both.": "استخدم خصم سلة ثابتاً أو بنسبة مئوية، لا كليهما.",
  "Use shared": "استخدام المشترك",
  "Use the AI assistant (read-only)": "استخدام المساعد الذكي (للقراءة فقط)",
  "Use the OpenRouter fallback, and I agree to send the same store data to OpenRouter":
    "استخدم بديل OpenRouter، وأوافق على إرسال بيانات المتجر نفسها إلى OpenRouter",
  "Use this computer as the store hub": "استخدام هذا الجهاز كخادم للمتجر",
  "Use this only when the hub reports its credential is missing or does not match. Every paired terminal will stop syncing until it is paired again; their unsynced sales stay safe on the terminal and upload after re-pairing.":
    "استخدم هذا فقط عندما يفيد الخادم بأن بيانات اعتماده مفقودة أو غير مطابقة. ستتوقف كل نقطة بيع مقترنة عن المزامنة حتى يُعاد اقترانها؛ وتبقى مبيعاتها غير المتزامنة آمنة على نقطة البيع وتُرفع بعد إعادة الاقتران.",
  "Use your tools to look at: {0}. Explain what needs attention and what I should do next.":
    "استخدم أدواتك لفحص: {0}. اشرح ما يحتاج إلى انتباه وما يجب أن أفعله بعد ذلك.",
