  "Create receiving draft": "إنشاء مسودة استلام",
  "The AI provider filled unresolved values. Check them again.":
    "ملأ مزود الذكاء الاصطناعي القيم غير المحسومة. راجعها مرة أخرى.",
  "The AI found nothing better to add.": "لم يجد الذكاء الاصطناعي ما يضيفه.",
