  "Mark reviewed and approved": "تعليم كمراجَعة ومعتمدة",
  "Void record": "إلغاء السجل",
  "Reads supplier invoices, credit notes and delivery notes (photos, scans, PDFs) for review against the original page. Creates drafts only: stock is posted when a person with receiving rights posts a receiving draft.":
    "يقرأ فواتير الموردين والإشعارات الدائنة وإشعارات التسليم (صور، مسح ضوئي، PDF) لمراجعتها مقابل الصفحة الأصلية. يُنشئ مسودات فقط: يُرحَّل المخزون عندما يرحّل شخص لديه صلاحية الاستلام مسودة استلام.",
  "Sends the OCR text of a supplier document to the configured AI provider to fill values the rules could not read. The answer is schema-checked, never overrides a person's correction, and is still reviewed by a person. Needs AI on and a real provider.":
    "يرسل نص التعرف الضوئي لمستند المورد إلى مزود الذكاء الاصطناعي المُعدّ لملء القيم التي لم تقرأها القواعد. يُتحقق من الإجابة وفق مخطط، ولا تتجاوز أبداً تصحيح شخص، ويراجعها شخص. يتطلب تشغيل الذكاء الاصطناعي ومزوداً حقيقياً.",
  "Reads incoming WhatsApp chats on the linked number into draft orders with real products, prices and stock. Staff review, answer and confirm every order; nothing is charged, sent or taken from stock automatically. Needs WhatsApp and digital orders.":
    "يقرأ محادثات واتساب الواردة على الرقم المرتبط إلى طلبات مسودة بمنتجات وأسعار ومخزون حقيقية. يراجع الموظفون كل طلب ويردّون عليه ويؤكدونه؛ لا يُحصَّل أو يُرسَل أو يُخصم من المخزون شيء تلقائياً. يتطلب واتساب والطلبات الرقمية.",
  "Shows staff products often bought with the items in a WhatsApp order. Suggestions are never sent to the customer automatically.":
    "يعرض للموظفين منتجات تُشترى غالباً مع أصناف طلب واتساب. لا تُرسل الاقتراحات للعميل تلقائياً أبداً.",
  "Collecting items": "جمع الأصناف",
  "Waiting for an answer": "بانتظار الرد",
