  "WhatsApp orders take the delivery fee from these zones: by block first, then by area. With no zone for an address the fee stays unresolved for a person to set.":
    "تأخذ طلبات واتساب رسوم التوصيل من هذه المناطق: حسب المجمع أولاً ثم حسب المنطقة. إذا لم توجد منطقة للعنوان تبقى الرسوم غير محسومة ليحددها شخص.",
  "Zone name": "اسم المنطقة",
  "Free delivery over": "توصيل مجاني فوق",
