  "You are handling this chat": "أنت تتولى هذه المحادثة",
  "New messages no longer change the order. Reply to the customer yourself.":
    "الرسائل الجديدة لا تغيّر الطلب. ردّ على العميل بنفسك.",
  "Waiting for the items": "بانتظار الأصناف",
  "Nothing to order yet. Ask the customer what they would like.": "لا يوجد ما يُطلب بعد. اسأل العميل عمّا يريد.",
  "Choose the right product": "اختر المنتج الصحيح",
  "Show me": "أرني",
  "Some words did not match a product. Tap Choose product on those lines.":
    'بعض الكلمات لم تطابق منتجًا. اضغط "اختيار منتج" في تلك الأسطر.',
  "Pick one of the items in stock instead, or remove it.": "اختر بديلًا متوفرًا أو احذف الصنف.",
  "Delivery or pickup?": "توصيل أم استلام؟",
  "The customer has not said. Ask them, or choose it below.": "لم يحدد العميل. اسأله أو اختر بالأسفل.",
  "Complete the address": "أكمل العنوان",
  "Add the block or choose a delivery zone so the fee is known.": "أضف رقم المجمع أو اختر منطقة التوصيل لمعرفة الرسوم.",
  "Which customer is this?": "من هو هذا العميل؟",
  "More than one customer has this number. Choose the right one.": "هذا الرقم مسجّل لأكثر من عميل. اختر العميل الصحيح.",
  "Everything is matched. Send the customer the total, then confirm the order.":
    "كل شيء مطابق. أرسل الإجمالي للعميل ثم أكّد الطلب.",
  "Customers' WhatsApp messages become draft orders with real products and prices. Follow the next step on each chat. Nothing is sent or charged until you do it.":
    "رسائل العملاء على واتساب تتحول إلى مسودات طلبات بمنتجات وأسعار حقيقية. اتبع الخطوة التالية في كل محادثة. لا يُرسل شيء ولا يُحصَّل أي مبلغ حتى تقوم بذلك.",
  "Hand back to automatic reading": "إعادة المحادثة للقراءة التلقائية",
  "Order {0} for {1} is confirmed and its items are held for 48 hours. No payment is taken now: a cashier rings it up at the till as usual.":
    "يُؤكَّد الطلب {0} بقيمة {1} وتُحجز أصنافه لمدة 48 ساعة. لا يُحصَّل أي مبلغ الآن: يسجّله الكاشير على نقطة البيع كالمعتاد.",
  "Not enough stock": "المخزون غير كافٍ",
  "The total has changed": "تغيّر الإجمالي",
  "Change the order": "تعديل الطلب",
  "Go back": "رجوع",
  "Confirm anyway": "تأكيد على أي حال",
  "Some items are short right now:": "بعض الأصناف ناقصة حاليًا:",
  "wanted {0}, available {1}": "المطلوب {0}، المتوفر {1}",
  "Change the order first, or confirm anyway: only the stock that is available is held for it.":
    "عدّل الطلب أولًا أو أكّده على أي حال: يُحجز له المتوفر فقط.",
  "The customer was told {0}. With today's prices it is {1}.": "أُبلغ العميل بمبلغ {0}. بأسعار اليوم أصبح {1}.",
  "Send the customer the new total first, or confirm anyway.": "أرسل الإجمالي الجديد للعميل أولًا أو أكّد على أي حال.",
  "Cancel order {0}?": "إلغاء الطلب {0}؟",
  "Keep the order": "الإبقاء على الطلب",
  "Any items held for it go back on sale. The customer is not messaged automatically.":
    "تعود أي أصناف محجوزة له للبيع. لا تُرسل رسالة للعميل تلقائيًا.",
  "Start packing": "بدء التجهيز",
  "Picked up, on the way": "استلمته، في الطريق",
  "Call the customer": "الاتصال بالعميل",
  Call: "اتصال",
  "Send out": "إرسال",
  "To do": "للتنفيذ",
  "Nothing to send. To deliver a sale, tap Send on the payment screen.":
    'لا يوجد ما يُرسل. لتوصيل عملية بيع، اضغط "إرسال" في شاشة الدفع.',
  "Nothing is on the way.": "لا يوجد شيء في الطريق.",
