  "Add supplier invoice": "إضافة فاتورة مورد",
  "You owe": "المستحق عليك",
  Overdue: "متأخر السداد",
  "Due in the next 7 days": "يستحق خلال 7 أيام",
  "{0} invoices to review, {1} ready to post": "{0} فواتير للمراجعة، {1} جاهزة للترحيل",
  "{0} invoices to review": "{0} فواتير للمراجعة",
  "{0} invoices ready to post": "{0} فواتير جاهزة للترحيل",
  "Show invoices": "عرض الفواتير",
  "Owed by how late it is": "المستحق حسب مدة التأخير",
