    "تقدّم هذا التوصيل منذ ذلك الحين؛ لا يمكن إرجاعه إلى {0}.",
  "Unknown payment state.": "حالة دفع غير معروفة.",
  "Unknown channel.": "قناة غير معروفة.",
  "Enter the date as YYYY-MM-DD.": "أدخل التاريخ بالصيغة YYYY-MM-DD.",
  "Unknown date range.": "نطاق تاريخ غير معروف.",
  "Enter dates as YYYY-MM-DD.": "أدخل التواريخ بالصيغة YYYY-MM-DD.",
