  "Choose a different destination.": "اختر وجهة مختلفة.",
  "Only products with stock tracking can be transferred.": "يمكن تحويل المنتجات التي يُتتبع مخزونها فقط.",
  "Only the sending branch can ship this transfer.": "يمكن للفرع المرسِل فقط شحن هذا التحويل.",
  "This transfer is already {0}.": "هذا التحويل {0} بالفعل.",
