  "WhatsApp catalogue prices support at most 3 decimals.": "أسعار كتالوج واتساب تدعم 3 خانات عشرية كحد أقصى.",
  "A WhatsApp catalogue price must be above zero.": "يجب أن يكون سعر كتالوج واتساب أكبر من صفر.",
  "The price is too large for WhatsApp.": "السعر كبير جدًا بالنسبة لواتساب.",
  "WhatsApp is not linked to a number yet.": "واتساب غير مرتبط برقم بعد.",
