  "This PDF is password-protected. Remove the password (or print it to a new PDF) and upload it again.":
    "ملف PDF هذا محمي بكلمة مرور. أزل كلمة المرور (أو اطبعه إلى ملف PDF جديد) ثم ارفعه مرة أخرى.",
  "The PDF is damaged or not a PDF, so it could not be read.": "ملف PDF تالف أو ليس PDF، لذا تعذّرت قراءته.",
  "The PDF has no pages.": "ملف PDF لا يحتوي صفحات.",
  "Choose a PDF or an image (JPG, PNG, WEBP, BMP or TIFF).":
    "اختر ملف PDF أو صورة (JPG أو PNG أو WEBP أو BMP أو TIFF).",
  "The file is empty.": "الملف فارغ.",
  "The file is larger than 20 MB.": "الملف أكبر من 20 ميغابايت.",
  "The file is not a PDF, although its name ends in .pdf.": "الملف ليس PDF رغم أن اسمه ينتهي بـ .pdf.",
  "This document is no longer waiting for review.": "هذا المستند لم يعد بانتظار المراجعة.",
  "Someone else changed this document (or its reading finished) while you were looking at it. Reload it and try again.":
    "غيّر شخص آخر هذا المستند (أو انتهت قراءته) أثناء عرضك له. أعد تحميله وحاول مرة أخرى.",
  "The file could not be read.": "تعذّرت قراءة الملف.",
  "Only images and documents can be read as supplier documents.": "يمكن قراءة الصور والمستندات فقط كمستندات موردين.",
  "The attachment has not been downloaded yet.": "لم يُنزَّل المرفق بعد.",
  "Attachment file": "ملف المرفق",
  "Unknown stage.": "مرحلة غير معروفة.",
  "Document type must be invoice, credit note, delivery note or unknown.":
    "يجب أن يكون نوع المستند فاتورة أو إشعارًا دائنًا أو إشعار تسليم أو غير معروف.",
  "The invoice number is too long.": "رقم الفاتورة أطول من المسموح.",
  "Dates are YYYY-MM-DD.": "التواريخ بالصيغة YYYY-MM-DD.",
  "The VAT rate must be between 0% and 100%.": "يجب أن تكون نسبة الضريبة بين 0٪ و100٪.",
  "That purchase order belongs to another supplier.": "أمر الشراء هذا لمورد آخر.",
  "Document line": "سطر المستند",
  "Unit must be pcs, ctn, pkt, box or kg.": "يجب أن تكون الوحدة: قطعة أو كرتون أو باكيت أو صندوق أو كغ.",
  "Units per case must be between 2 and 1,000.": "يجب أن يكون عدد الوحدات في الكرتون بين 2 و1,000.",
  "Choose the supplier first.": "اختر المورد أولًا.",
  "Confirm the document type (invoice or credit note) first.": "أكّد نوع المستند (فاتورة أو إشعار دائن) أولًا.",
  "Line {0} needs a quantity and an amount (or exclude it).": "السطر {0} يحتاج كمية ومبلغًا (أو استبعده).",
  "A supplier invoice was already created from this document.": "أُنشئت فاتورة مورد من هذا المستند بالفعل.",
  "A credit note does not receive stock. Create a supplier credit draft instead.":
    "الإشعار الدائن لا يُدخل مخزونًا. أنشئ مسودة رصيد دائن للمورد بدلًا من ذلك.",
  "Confirm the document type first.": "أكّد نوع المستند أولًا.",
  "Line {0} is not matched to a product: match it, create the product first, or exclude it.":
    "السطر {0} غير مطابق لمنتج: طابقه، أو أنشئ المنتج أولًا، أو استبعده.",
  "Line {0} is a return (negative). Returns do not receive stock: exclude it and record it as a supplier credit.":
    "السطر {0} مرتجع (سالب). المرتجعات لا تُدخل مخزونًا: استبعده وسجّله كرصيد دائن للمورد.",
  "Line {0} needs a quantity and a cost.": "السطر {0} يحتاج كمية وتكلفة.",
  "A receiving draft already exists for this document.": "توجد مسودة استلام لهذا المستند بالفعل.",
  "Only a draft can be edited.": "يمكن تعديل المسودة فقط.",
  "Only a draft can be cancelled.": "يمكن إلغاء المسودة فقط.",
  "A valid operation id (16–56 characters) is required.": "مطلوب معرّف عملية صالح (16–56 حرفًا).",
  "Only a draft can be posted.": "يمكن ترحيل المسودة فقط.",
  "The draft has no lines.": "المسودة لا تحتوي أسطرًا.",
  "Purchase order {0} is {1}: place the order first (Purchasing), then post this receiving.":
    "أمر الشراء {0} حالته {1}: أرسل الأمر أولًا (المشتريات)، ثم رحّل هذا الاستلام.",
  "Status must be approved or void.": "يجب أن تكون الحالة معتمدة أو ملغاة.",
  "This supplier invoice is posted: reverse it in Payables instead.":
    "فاتورة المورد هذه مرحّلة: اعكسها من صفحة المستحقات للموردين بدلًا من ذلك.",
  "This supplier invoice can no longer be changed.": "لم يعد بالإمكان تغيير فاتورة المورد هذه.",
  "Filter must be open, attention or all.": "يجب أن يكون المرشح: مفتوح أو يحتاج انتباهًا أو الكل.",
  "This conversation's order is no longer open.": "طلب هذه المحادثة لم يعد مفتوحًا.",
  "New messages or another person changed this order. Reload it and try again.":
    "غيّرت رسائل جديدة أو شخص آخر هذا الطلب. أعد تحميله وحاول مرة أخرى.",
  "The order is no longer a draft; change it on the Orders page.": "الطلب لم يعد مسودة؛ غيّره من صفحة الطلبات.",
  "Choose a product.": "اختر منتجًا.",
  "Mode must be delivery, pickup or unknown.": "يجب أن يكون النوع توصيلًا أو استلامًا أو غير محدد.",
  "There is no draft to confirm yet.": "لا توجد مسودة لتأكيدها بعد.",
  "Some items are out of stock: replace or remove them first.": "بعض الأصناف غير متوفرة: استبدلها أو احذفها أولًا.",
  "The total changed since it was sent to the customer ({0} → {1} BHD). Send the new total, or confirm the change.":
    "تغيّر الإجمالي منذ إرساله للعميل ({0} ← {1} د.ب). أرسل الإجمالي الجديد أو أكّد التغيير.",
  "Decision must be verified or rejected.": "يجب أن يكون القرار تحققًا أو رفضًا.",
  "There is no draft for this conversation.": "لا توجد مسودة لهذه المحادثة.",
  "That screenshot is not attached to this order.": "هذه اللقطة غير مرفقة بهذا الطلب.",
  "This screenshot was already decided.": "تم البت في هذه اللقطة بالفعل.",
